import{_ as i,a0 as p,w as o,s as r,I as s,x as e,a1 as n,A as l,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"在 Ubuntu Mate 16.04 上通过 PPA  升级 Mate 1.14 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu Mate 16.04 上通过 PPA  升级 Mate 1.14 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu Mate 16.04 上通过 PPA  升级 Mate 1.14 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu Mate 16.04 上通过 PPA  升级 Mate 1.14 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160609 INSTALL MATE 1.14 IN UBUNTU MATE 16.04  VIA PPA","title":"在 Ubuntu Mate 16.04 上通过 PPA  升级 Mate 1.14","tag":"201607","desc":""},"relativePath":"201607/20160609 INSTALL MATE 1.14 IN UBUNTU MATE 16.04  VIA PPA.md","filePath":"[post].md"}'),d={name:"201607/20160609 INSTALL MATE 1.14 IN UBUNTU MATE 16.04  VIA PPA.md"};function A(T,t,b,m,M,g){const a=p("Link");return o(),r("div",null,[t[21]||(t[21]=s("h1",{id:"在-ubuntu-mate-16-04-上通过-ppa-升级-mate-1-14",tabindex:"-1"},[e("在 Ubuntu Mate 16.04 上通过 PPA 升级 Mate 1.14 "),s("a",{class:"header-anchor",href:"#在-ubuntu-mate-16-04-上通过-ppa-升级-mate-1-14","aria-label":"Permalink to “在 Ubuntu Mate 16.04 上通过 PPA  升级 Mate 1.14”"},"​")],-1)),s("p",null,[t[1]||(t[1]=e('Mate 桌面环境 1.14 现在可以在 Ubuntu Mate 16.04 ("Xenial Xerus") 上使用了。根据这个',-1)),n(a,{href:"https://ubuntu-mate.org/blog/mate-desktop-114-for-xenial-xerus/"},{default:l(()=>[...t[0]||(t[0]=[e("发布版本",-1)])]),_:1}),t[2]||(t[2]=e("的描述，为了全面测试 Mate 1.14，所以 Mate 桌面环境 1.14 已经在 PPA 上发布 2 个月了。因此，你不太可能遇到安装的问题。",-1))]),t[22]||(t[22]=u('<p><img src="https://2.bp.blogspot.com/-v38tLvDAxHg/V1k7beVd5SI/AAAAAAAAX7A/1X72bmQ3ia42ww6kJ_61R-CZ6yrYEBSpgCLcB/s400/mate114-ubuntu1604.png" alt=""></p><p><strong>现在 PPA 提供 Mate 1.14.1 包含如下改变（Ubuntu Mate 16.04 默认安装的是 Mate 1.12.x）：</strong></p><ul><li>客户端的装饰应用现在可以正确的在所有主题中渲染；</li><li>触摸板配置现在支持边缘操作和双指滚动；</li><li>在 Caja 中的 Python 扩展可以被单独管理；</li><li>所有三个窗口焦点模式都是可选的；</li><li>Mate Panel 中的所有菜单栏图标和菜单图标可以改变大小；</li><li>音量和亮度 OSD 目前可以启用和禁用；</li><li>更多的改进和 bug 修改；</li></ul><p>Mate 1.14 同时改进了整个桌面环境中对 GTK+ 3 的支持，包括各种 GTK+3 小应用。但是，Ubuntu MATE 的博客中提到：PPA 的发行包使用 GTK+ 2 编译是“为了确保对 Ubuntu MATE 16.04 还有各种各样的第三方 MATE 应用、插件、扩展的支持&quot;。</p>',4)),s("p",null,[t[4]||(t[4]=e("MATE 1.14 的完整修改列表",-1)),n(a,{href:"http://mate-desktop.com/blog/2016-04-08-mate-1-14-released/"},{default:l(()=>[...t[3]||(t[3]=[e("点击此处",-1)])]),_:1}),t[5]||(t[5]=e("阅读。",-1))]),t[23]||(t[23]=u(`<h3 id="在-ubuntu-mate-16-04-中升级-mate-1-14-x" tabindex="-1">在 Ubuntu MATE 16.04 中升级 MATE 1.14.x <a class="header-anchor" href="#在-ubuntu-mate-16-04-中升级-mate-1-14-x" aria-label="Permalink to “在 Ubuntu MATE 16.04 中升级 MATE 1.14.x”">​</a></h3><p>在 Ubuntu MATE 16.04 中打开终端，并且输入如下命令，来从官方的 Xenial MATE PPA 中升级最新的 MATE 桌面环境:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-add-repository ppa:ubuntu-mate-dev/xenial-mate</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt dist-upgrade</span></span></code></pre></div><p><strong>注意</strong>: mate-netspeed 应用将会在升级中删除。因为该应用现在已经是 mate-applets 应用报的一部分，所以它依旧是可以使用的。</p><p>一旦升级完成，请重启你的系统，享受全新的 MATE!</p><h3 id="如何回滚这次升级" tabindex="-1">如何回滚这次升级 <a class="header-anchor" href="#如何回滚这次升级" aria-label="Permalink to “如何回滚这次升级”">​</a></h3><p>如果你并不满意 MATE 1.14, 比如你遭遇了一些 bug 。或者你想回到 MATE 的官方源版本，你可以使用如下的命令清除 PPA，并且下载降级包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install ppa-purge</span></span>
<span class="line"><span>sudo ppa-purge ppa:ubuntu-mate-dev/xenial-mate</span></span></code></pre></div><p>在所有的 MATE 包降级之后，重启系统。</p>`,9)),s("p",null,[t[7]||(t[7]=e("via ",-1)),n(a,{href:"https://ubuntu-mate.org/blog/mate-desktop-114-for-xenial-xerus/"},{default:l(()=>[...t[6]||(t[6]=[e("Ubuntu MATE blog",-1)])]),_:1})]),t[24]||(t[24]=s("hr",null,null,-1)),s("p",null,[t[9]||(t[9]=e("via: ",-1)),n(a,{href:"http://www.webupd8.org/2016/06/install-mate-114-in-ubuntu-mate-1604.html"},{default:l(()=>[...t[8]||(t[8]=[e("http://www.webupd8.org/2016/06/install-mate-114-in-ubuntu-mate-1604.html",-1)])]),_:1})]),s("p",null,[t[13]||(t[13]=e("作者：",-1)),n(a,{href:"http://www.webupd8.org/p/about.html"},{default:l(()=>[...t[10]||(t[10]=[e("Andrew",-1)])]),_:1}),t[14]||(t[14]=e(" 译者：",-1)),n(a,{href:"https://github.com/MikeCoder"},{default:l(()=>[...t[11]||(t[11]=[e("MikeCoder",-1)])]),_:1}),t[15]||(t[15]=e(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:l(()=>[...t[12]||(t[12]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[18]||(t[18]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[16]||(t[16]=[e("LCTT",-1)])]),_:1}),t[19]||(t[19]=e(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:l(()=>[...t[17]||(t[17]=[e("Linux中国",-1)])]),_:1}),t[20]||(t[20]=e(" 荣誉推出",-1))])])}const x=i(d,[["render",A]]);export{k as __pageData,x as default};
